{
  "packet_id": "H6-T01-1",
  "claim_id": "C062",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C062.component",
    "value": "Observation should be extended when evidence is sparse.",
    "scope": "Conditional on sparse evidence; neither the sparsity threshold nor extension duration is specified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P028",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly states the conditional recommendation to extend observation."
    }
  },
  "signal_basis": {
    "component_id": "C062.signal_basis",
    "value": "Monitoring booking counts and recording completeness reveals evidence too sparse to apply the persistence rule reliably; the two-week window and small subgroup counts may be insufficient.",
    "scope": "Evidence adequacy during the equipment-turnaround investigation, assessed through daily review and weekly summaries.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans specify monitoring counts and completeness, identify sparsity that prevents applying the rule, and acknowledge insufficient observation windows and subgroup counts."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C062.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to license this bounded recommendation."
    }
  },
  "rationale": "Sparse evidence limits assessment of persistence across comparable observations. Extending observation is therefore warranted as an information-gathering response. The claim does not promise that extension will establish a bottleneck or resolve every source of uncertainty.",
  "uncertainty": "The mapping specifies neither how sparse evidence must be nor how long observation should continue; these limits leave implementation open without defeating the recommendation.",
  "anomalies": []
}
